import React,{useEffect,useId,useMemo,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {SvgIcon,MobileStepper,useMediaQuery,useTheme,Accordion,AccordionSummary,AccordionDetails,RadioGroup,Stepper,Step,StepLabel,IconButton,Alert,AppBar,Box,Button,Checkbox,Chip,Container,CssBaseline,Dialog,DialogActions,DialogContent,DialogTitle,Divider,FormControlLabel,LinearProgress,MenuItem,Paper,Radio,Stack,Tab,Tabs,Table,TableBody,TableCell,TableContainer,TableHead,TableRow,TextField,ThemeProvider,Toolbar,Typography} from '@mui/material';
import QRCode from 'qrcode';
import './styles.css';
